+/// Whether the end of `text` is inside a `/* ... */` block comment that opened
+/// outside a double-quoted string earlier in `text`.
+fn in_block_comment(text: &str) -> bool {
+    let mut in_string = false;
+    let mut escaped = false;
+    let mut in_comment = false;
+    let mut skip = 0;
+    for (index, c) in text.char_indices() {
+        if skip > 0 {
+            skip -= 1;
+        } else if in_comment {
+            if text[index..].starts_with("*/") {
+                in_comment = false;
+                skip = 1;
+            }
+        } else if in_string {
+            if escaped {
+                escaped = false;
+            } else if c == '\\' {
+                escaped = true;
+            } else if c == '"' {
+                in_string = false;
+            }
+        } else if c == '"' {
+            in_string = true;
+        } else if text[index..].starts_with("/*") {
+            in_comment = true;
+            skip = 1;
+        }
+    }
+    in_comment
+}
